using System.Security.Claims;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.RateLimiting;
using System.Threading.RateLimiting;
using Sales360.Api;
using Sales360.Domain;
using Npgsql;
using Microsoft.AspNetCore.DataProtection;

var builder=WebApplication.CreateBuilder(args);
builder.Logging.ClearProviders();builder.Logging.AddConsole();
builder.WebHost.UseUrls(Environment.GetEnvironmentVariable("SALES360_URL")??"http://127.0.0.1:5080");
builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.Cookie.Name="sales360.session";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Strict;o.ExpireTimeSpan=TimeSpan.FromHours(8);o.SlidingExpiration=false;o.Events.OnValidatePrincipal=Accounts.ValidateSession;o.Events.OnRedirectToLogin=c=>{c.Response.StatusCode=401;return Task.CompletedTask;};o.Events.OnRedirectToAccessDenied=c=>{c.Response.StatusCode=403;return Task.CompletedTask;};});
builder.Services.AddAuthorization();
builder.Services.AddRateLimiter(o=>{o.AddPolicy("login",context=>RateLimitPartition.GetFixedWindowLimiter(context.Connection.RemoteIpAddress?.ToString()??"local",_=>new FixedWindowRateLimiterOptions{PermitLimit=10,Window=TimeSpan.FromMinutes(1)}));o.RejectionStatusCode=429;});
builder.Services.AddRateLimiter(o=>o.AddPolicy("identity",context=>RateLimitPartition.GetFixedWindowLimiter(context.Connection.RemoteIpAddress?.ToString()??"local",_=>new FixedWindowRateLimiterOptions{PermitLimit=20,Window=TimeSpan.FromMinutes(1)})));
var connection=Environment.GetEnvironmentVariable("SALES360_DB")??throw new InvalidOperationException("Configure SALES360_DB; see scripts/start-local.ps1.");
var store=new Store(connection); builder.Services.AddSingleton(store);
var root=Path.GetFullPath(Environment.GetEnvironmentVariable("SALES360_ROOT")??Path.Combine(builder.Environment.ContentRootPath,"../.."));
var data=Path.GetFullPath(Environment.GetEnvironmentVariable("SALES360_DATA")??Path.Combine(root,"data"));Directory.CreateDirectory(data);
if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException("This build protects authentication keys using Windows DPAPI. Configure a managed key provider before porting.");
builder.Services.AddDataProtection().PersistKeysToFileSystem(new DirectoryInfo(Path.Combine(data,"keys"))).ProtectKeysWithDpapi();
await using(var c=await store.Open()) { await Store.Exec(c,await File.ReadAllTextAsync(Path.Combine(builder.Environment.ContentRootPath,"schema.sql"))); }
if(Environment.GetEnvironmentVariable("SALES360_SEED")=="1") await Seed.Run(store,data);
if(Environment.GetEnvironmentVariable("SALES360_BOOTSTRAP_PASSWORD") is string initialPassword && initialPassword.Length>=12)
    await OfflineBootstrap.Run(store,initialPassword);
builder.Services.AddSingleton<IdentityMail>(sp=>new IdentityMail(store,sp.GetRequiredService<IDataProtectionProvider>(),builder.Environment,data));
builder.Services.AddHostedService(sp=>sp.GetRequiredService<IdentityMail>());
if(Environment.GetEnvironmentVariable("SALES360_SETUP_TOKEN_HASH") is string setupHash)await Enrollment.Initialize(store,setupHash);
var app=builder.Build();
app.Use(async(ctx,next)=>{
    ctx.Response.Headers["X-Content-Type-Options"]="nosniff";ctx.Response.Headers["X-Frame-Options"]="DENY";ctx.Response.Headers["Referrer-Policy"]="no-referrer";ctx.Response.Headers["Content-Security-Policy"]="default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self'; img-src 'self' data:; frame-ancestors 'none'; base-uri 'self'; form-action 'self'";
    if(ctx.Request.Path.StartsWithSegments("/api/auth")||ctx.Request.Path=="/api/me"||ctx.Request.Path=="/api/users")ctx.Response.Headers.CacheControl="no-store";
    if(ctx.Request.Method is not ("GET" or "HEAD" or "OPTIONS") && ctx.Request.Headers["X-Sales360-Request"]!="1") {ctx.Response.StatusCode=400;await ctx.Response.WriteAsJsonAsync(new{error="Missing request protection header."});return;}
    try {await next();} catch(Exception ex) when(ex is RuleException or KeyNotFoundException or PostgresException or UnauthorizedAccessException or FormatException or JsonException or InvalidDataException or ArgumentException) {ctx.Response.StatusCode=ex is UnauthorizedAccessException?403:ex is KeyNotFoundException?404:409;await ctx.Response.WriteAsJsonAsync(new{error=ex is PostgresException?"Database constraint prevented this change. Check duplicates, links and immutable history.":ex is InvalidDataException or ArgumentException?"Invalid input or unsupported workbook format. Check the uploaded file and field values.":ex.Message});}
});
app.UseRateLimiter();app.UseAuthentication();app.Use(AreaAccess.Check);app.UseAuthorization();
string Company(HttpContext h)=>h.User.FindFirstValue("company")??throw new UnauthorizedAccessException();
string Actor(HttpContext h)=>h.User.FindFirstValue(ClaimTypes.NameIdentifier)??throw new UnauthorizedAccessException();
void Role(HttpContext h,params string[] roles) {if(!h.User.IsInRole("Administrator")&&!roles.Any(h.User.IsInRole))throw new UnauthorizedAccessException("Your role cannot perform this action.");}
string Id()=>Guid.NewGuid().ToString("N");
string Today()=>TimeZoneInfo.ConvertTimeBySystemTimeZoneId(DateTimeOffset.UtcNow,"Arabian Standard Time").ToString("yyyy-MM-dd");
app.MapGet("/api/health",()=>new{status="ok",version="0.9.1",mode=Environment.GetEnvironmentVariable("SALES360_MAIL_MODE")=="Offline"?"Offline":"Local development",schema=9,instance=Environment.GetEnvironmentVariable("SALES360_INSTANCE")});
app.MapPost("/api/login",async(HttpContext h,JsonObject input)=>{
    var login=input.Text("email")!=""?input.Text("email"):input.Text("username");await using var c=await store.Open();var users=await Store.Rows(c,"SELECT * FROM app_user WHERE (lower(email)=lower(@p0) OR (email IS NULL AND id=@p0) OR lower(username)=lower(@p0)) AND active AND account_status='Approved' AND (email IS NULL OR email_verified OR @p1)",login,app.Services.GetRequiredService<IdentityMail>().IsOffline);
    if(users.Count!=1 || Accounts.Secret(input).Length>128 || !Store.Verify(Accounts.Secret(input),users[0]!.Text("password_hash")))return Results.Json(new{error="Invalid credentials, or your account is awaiting email verification and Administrator approval."},statusCode:401);
    var u=users[0]!.AsObject();await Accounts.SignIn(h,u);
    return Results.Ok(new{name=u.Text("name"),role=u.Text("role"),accessRole=u.Text("access_role")});
}).RequireRateLimiting("login");
var api=app.MapGroup("/api").RequireAuthorization();
Accounts.Map(app,api,store,app.Services.GetRequiredService<IdentityMail>());
Enrollment.Map(app,store,app.Services.GetRequiredService<IdentityMail>());
api.MapGet("/me",(HttpContext h)=>new{id=Actor(h),name=h.User.Identity!.Name,role=h.User.FindFirstValue("workflow_role"),accessRole=h.User.FindFirstValue(ClaimTypes.Role),email=h.User.FindFirstValue("email"),workAreas=AreaAccess.Granted(h.User),company=Company(h)});
Organization.Map(api,store,Company,Actor);
CustomerMaster.Map(api,store,Company,Actor);
ProjectMaster.Map(api,store);
WorkbookImports.Map(api,store,data,Company,Actor);
Analytics.Map(api,store,root,data);
Vat.Map(api,store,root,data);
SupportTools.Map(api,store,root,data);
api.MapPost("/logout",async(HttpContext h)=>{await h.SignOutAsync();return Results.Ok();});
api.MapGet("/customers",async(HttpContext h)=>{await using var c=await store.Open();return await Store.Rows(c,"SELECT * FROM customer WHERE company_id=@p0 ORDER BY code",Company(h));});
api.MapPost("/customers",async(HttpContext h,JsonObject b)=>{Role(h,"Accountant","Finance Administrator","Super user");return await store.Transaction(Company(h),async c=>{
    Billing.Require(b.Text("code").Length>0&&b.Text("name").Length>1,"Customer code and legal name are required.");var trn=b.Text("trn");Billing.Require(trn==""||System.Text.RegularExpressions.Regex.IsMatch(trn,"^[0-9]{15}$"),"UAE TRN must contain 15 digits.");var id=Id();
    await Store.Exec(c,"INSERT INTO customer(id,company_id,code,name,email,trn) VALUES(@p0,@p1,@p2,@p3,@p4,@p5)",id,Company(h),b.Text("code"),b.Text("name"),b.Text("email"),trn);await Store.Audit(c,Company(h),Actor(h),"Customer created",id,b);return new{id};});});
api.MapGet("/projects",async(HttpContext h,string? q,int? page)=>{await using var c=await store.Open();var p=Math.Max(1,page??1);return new{page=p,pageSize=24,total=(await Store.One(c,"SELECT count(*) AS count FROM project WHERE company_id=@p0 AND (name ILIKE @p1 OR code ILIKE @p1)",Company(h),"%"+(q??"")+"%")).Integer("count"),items=await Store.Rows(c,"SELECT p.*,c.name AS customer FROM project p JOIN customer c ON c.id=p.customer_id WHERE p.company_id=@p0 AND (p.name ILIKE @p1 OR p.code ILIKE @p1) ORDER BY p.code LIMIT 24 OFFSET @p2",Company(h),"%"+(q??"")+"%",(p-1)*24)};});
api.MapPost("/projects",async(HttpContext h,JsonObject b)=>{Role(h,"Accountant","Finance Administrator","Super user");return await store.Transaction(Company(h),async c=>{
    await Store.One(c,"SELECT id FROM customer WHERE company_id=@p0 AND id=@p1",Company(h),b.Text("customer_id"));Billing.Require(b.Text("code")!=""&&b.Text("name")!=""&&Billing.Categories.Contains(b.Text("category"))&&b.Decimal("fee")>0,"Provide project code, name, category and positive fee.");var id=Id();
    await Store.Exec(c,"INSERT INTO project(id,company_id,customer_id,code,name,category,fee,location,stages) VALUES(@p0,@p1,@p2,@p3,@p4,@p5,@p6,@p7,@p8::jsonb)",id,Company(h),b.Text("customer_id"),b.Text("code"),b.Text("name"),b.Text("category"),b.Decimal("fee"),b.Text("location"),Seed.Stages());await Store.Audit(c,Company(h),Actor(h),"Project created",id,b);return new{id};});});
api.MapGet("/projects/{id}",async(HttpContext h,string id)=>{await using var c=await store.Open();return await Store.One(c,"SELECT p.*,c.name AS customer,c.terms,greatest(coalesce((SELECT sum(net) FROM invoice WHERE project_id=p.id),0)-coalesce((SELECT sum(f.net) FROM financial_correction f JOIN invoice i ON i.id=f.invoice_id WHERE i.project_id=p.id AND f.kind='Credit note'),0),coalesce((SELECT max(cumulative) FROM certificate WHERE project_id=p.id AND state='Approved'),0)) AS opening_required_net,(SELECT stages FROM certificate WHERE project_id=p.id AND state='Approved' ORDER BY cumulative DESC LIMIT 1) AS latest_approved_stages FROM project p JOIN customer c ON c.id=p.customer_id WHERE p.company_id=@p0 AND p.id=@p1",Company(h),id);});
api.MapGet("/certificates",async(HttpContext h)=>{await using var c=await store.Open();return await Store.Rows(c,"SELECT x.*,p.name AS project,c.name AS customer FROM certificate x JOIN project p ON p.id=x.project_id JOIN customer c ON c.id=x.customer_id WHERE x.company_id=@p0 ORDER BY x.claim_date DESC,x.reference",Company(h));});
api.MapPost("/certificates",async(HttpContext h,JsonObject b)=>{Role(h,"Accountant");return await store.Transaction(Company(h),async c=>{
    var p=await Store.One(c,"SELECT p.*,cu.terms FROM project p JOIN customer cu ON cu.id=p.customer_id WHERE p.company_id=@p0 AND p.id=@p1",Company(h),b.Text("project_id"));Billing.Require(p.Text("status")=="Active","Only active projects can be billed.");
    var baseline=p["stages"]!.Deserialize<List<Stage>>(new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;var lines=b["stages"]!.Deserialize<List<Stage>>(new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;
    Billing.Require(lines.Count==baseline.Count&&lines.Zip(baseline).All(pair=>pair.First.Name==pair.Second.Name&&pair.First.Allocation==pair.Second.Allocation),"Use the approved project fee schedule; variations need review.");
    var previous=await Store.Rows(c,"SELECT stages,cumulative FROM certificate WHERE company_id=@p0 AND project_id=@p1 AND state='Approved' ORDER BY cumulative DESC,claim_date DESC,reference DESC LIMIT 1",Company(h),p.Text("id"));
    var prev=previous.Count>0?previous[0]!["stages"]!.Deserialize<List<Stage>>(new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!:baseline.Select(s=>s with{Assessed=0,Previous=0}).ToList();
    if(p.Decimal("opening_net")>(previous.Count>0?previous[0]!.Decimal("cumulative"):0))prev=p["opening_assessments"]!.Deserialize<List<Stage>>()!;
    lines=lines.Select((line,i)=>line with{Previous=prev[i].Assessed}).ToList();var a=Billing.Assess(p.Decimal("fee"),lines);var id=Id();var date=b.Date("claim_date");var refno="PC/"+p.Text("code")+"/"+Id()[..8].ToUpperInvariant();var json=JsonSerializer.Serialize(lines);
    await Store.Exec(c,"INSERT INTO certificate(id,company_id,project_id,customer_id,reference,prepared_by,claim_date,due_date,fee,stages,cumulative,previous,settlement,snapshot_hash) VALUES(@p0,@p1,@p2,@p3,@p4,@p5,@p6,@p7,@p8,@p9::jsonb,@p10,@p11,@p12,@p13)",id,Company(h),p.Text("id"),p.Text("customer_id"),refno,Actor(h),date,date.AddDays(p.Integer("terms")),p.Decimal("fee"),json,a.Cumulative,a.Previous,a.Settlement,Store.Hash(json+p.Text("fee")+date));
    await Store.Audit(c,Company(h),Actor(h),"Certificate prepared",id,new{a.Settlement,refno});return new{id};});});
api.MapPost("/certificates/{id}/transition",async(HttpContext h,string id,JsonObject b)=>await store.Transaction(Company(h),async c=>{
    var x=await Store.One(c,"SELECT * FROM certificate WHERE company_id=@p0 AND id=@p1 FOR UPDATE",Company(h),id);var state=x.Text("state");var action=b.Text("action");Billing.Require(new[]{"submit","return","approve"}.Contains(action),"Unknown certificate action.");var approvals=x["approvals"]!.AsArray();
    if(action=="submit") {Role(h,"Accountant");Billing.Require((h.User.IsInRole("Administrator")||x.Text("prepared_by")==Actor(h))&&state=="Draft","Only the preparer may submit a draft.");state="Submitted";}
    else if(action=="return") {Billing.Require(state is "Submitted" or "Reviewed 1" or "Reviewed 2","Only pending certificates can be returned.");Role(h,Billing.NextApproval(state));Billing.Require(b.Text("reason").Length>3,"A return reason is required.");state="Returned";}
    else { if(state=="Approved"){Role(h,"Approver");return new{id,state};} var role=Billing.NextApproval(state);Role(h,role);Billing.Require(h.User.IsInRole("Administrator")||(Actor(h)!=x.Text("prepared_by")&&!approvals.Any(a=>a!.Text("actor")==Actor(h))),"Preparation and approval stages require distinct users.");
        // Certifying an overlapping draft is blocked, even if its snapshot was prepared earlier.
        if(role=="Approver") {var prior=(await Store.One(c,"SELECT coalesce(max(cumulative),0) AS value FROM certificate WHERE company_id=@p0 AND project_id=@p1 AND state='Approved' AND id<>@p2",Company(h),x.Text("project_id"),id)).Decimal("value");var openingRecord=await Store.One(c,"SELECT opening_net,status FROM project WHERE company_id=@p0 AND id=@p1",Company(h),x.Text("project_id"));Billing.Require(openingRecord.Text("status")=="Active","Review the imported project opening assessment before final approval.");var opening=openingRecord.Decimal("opening_net");Billing.Require(Math.Max(prior,opening)==x.Decimal("previous"),"A competing certificate changed the previously certified balance. Prepare a fresh assessment.");}
        approvals.Add(new JsonObject{["actor"]=Actor(h),["role"]=role,["administrator_override"]=h.User.IsInRole("Administrator"),["at"]=DateTimeOffset.UtcNow,["hash"]=x.Text("snapshot_hash"),["comment"]=b.Text("reason")});state=role=="Reviewer 1"?"Reviewed 1":role=="Reviewer 2"?"Reviewed 2":"Approved";
        if(state=="Approved")await Store.Exec(c,"INSERT INTO draft_invoice(id,company_id,certificate_id,reference) VALUES(@p0,@p1,@p2,@p3) ON CONFLICT(certificate_id) DO NOTHING",Id(),Company(h),id,"DRAFT/"+x.Text("reference"));
    }
    await Store.Exec(c,"UPDATE certificate SET state=@p0,approvals=@p1::jsonb WHERE id=@p2",state,approvals.ToJsonString(),id);await Store.Audit(c,Company(h),Actor(h),"Certificate "+action,id,new{state,reason=b.Text("reason"),administratorOverride=h.User.IsInRole("Administrator")});return new{id,state};}));
api.MapGet("/drafts",async(HttpContext h)=>{await using var c=await store.Open();return await Store.Rows(c,"SELECT d.*,x.project_id,x.customer_id,x.settlement,x.claim_date,x.due_date,p.name AS project,c.name AS customer FROM draft_invoice d JOIN certificate x ON x.id=d.certificate_id JOIN project p ON p.id=x.project_id JOIN customer c ON c.id=x.customer_id WHERE d.company_id=@p0 ORDER BY d.reference",Company(h));});
api.MapPost("/certificates/{id}/edit",async(HttpContext h,string id,JsonObject b)=>{Role(h,"Accountant");return await store.Transaction(Company(h),async c=>{var x=await Store.One(c,"SELECT * FROM certificate WHERE company_id=@p0 AND id=@p1",Company(h),id);Billing.Require(x.Text("state")=="Draft"&&(h.User.IsInRole("Administrator")||x.Text("prepared_by")==Actor(h)),"Only the preparer can edit a draft revision; submitted content must be returned and revised.");var old=x["stages"]!.Deserialize<List<Stage>>(new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;var lines=b["stages"]!.Deserialize<List<Stage>>(new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;Billing.Require(old.Count==lines.Count&&old.Zip(lines).All(p=>p.First.Name==p.Second.Name&&p.First.Allocation==p.Second.Allocation),"Approved schedule allocations cannot change here.");lines=lines.Select((s,i)=>s with{Previous=old[i].Previous}).ToList();var a=Billing.Assess(x.Decimal("fee"),lines);var json=JsonSerializer.Serialize(lines);await Store.Exec(c,"UPDATE certificate SET stages=@p0::jsonb,cumulative=@p1,previous=@p2,settlement=@p3,snapshot_hash=@p4 WHERE id=@p5",json,a.Cumulative,a.Previous,a.Settlement,Store.Hash(json+x.Text("fee")+x.Text("claim_date")),id);await Store.Audit(c,Company(h),Actor(h),"Draft certificate edited",id,new{before=x["stages"],after=lines});return new{id};});});
api.MapPost("/certificates/{id}/revise",async(HttpContext h,string id)=>{Role(h,"Accountant");return await store.Transaction(Company(h),async c=>{var x=await Store.One(c,"SELECT * FROM certificate WHERE company_id=@p0 AND id=@p1",Company(h),id);Billing.Require((h.User.IsInRole("Administrator")||x.Text("prepared_by")==Actor(h))&&x.Text("state")=="Returned","Only the original preparer can revise a returned certificate.");var existing=await Store.Rows(c,"SELECT id FROM certificate WHERE company_id=@p0 AND reference=@p1 AND revision>@p2",Company(h),x.Text("reference"),x.Integer("revision"));if(existing.Count>0)return existing[0]!;var next=Id();await Store.Exec(c,"INSERT INTO certificate(id,company_id,project_id,customer_id,reference,revision,state,prepared_by,claim_date,due_date,fee,stages,cumulative,previous,settlement,snapshot_hash) SELECT @p0,company_id,project_id,customer_id,reference,revision+1,'Draft',prepared_by,claim_date,due_date,fee,stages,cumulative,previous,settlement,snapshot_hash FROM certificate WHERE id=@p1",next,id);await Store.Audit(c,Company(h),Actor(h),"Returned certificate revised",next,new{previous=id,revision=x.Integer("revision")+1,approvalsInvalidated=true});return new JsonObject{["id"]=next};});});
api.MapPost("/drafts/{id}/confirm",async(HttpContext h,string id,JsonObject b)=>{Role(h,"Accountant","Finance Administrator");return await store.Transaction(Company(h),async c=>{
    var x=await Store.One(c,"SELECT d.*,x.snapshot_hash,x.settlement FROM draft_invoice d JOIN certificate x ON x.id=d.certificate_id WHERE d.company_id=@p0 AND d.id=@p1",Company(h),id);Billing.Require(x.Text("status")!="Issued","Issued invoice is immutable.");Billing.Require(b.Text("person").Length>2&&b.Text("evidence").Length>5,"Confirming person and evidence reference are required.");Billing.Require(b.Decimal("amount")==x.Decimal("settlement"),"Confirmation must match the draft settlement.");
    b["hash"]=x.Text("snapshot_hash");b["actor"]=Actor(h);b["at"]=DateTimeOffset.UtcNow;await Store.Exec(c,"UPDATE draft_invoice SET confirmation=@p0::jsonb,status='Client confirmed' WHERE id=@p1",b.ToJsonString(),id);await Store.Audit(c,Company(h),Actor(h),"Client confirmation recorded",id,b);return new{id};});});
api.MapPost("/drafts/{id}/issue",async(HttpContext h,string id,JsonObject b)=>{Role(h,"Finance Administrator");return await store.Transaction(Company(h),async c=>{
    var d=await Store.One(c,"SELECT d.*,x.project_id,x.customer_id,x.snapshot_hash,x.state,x.settlement,x.due_date,p.category FROM draft_invoice d JOIN certificate x ON x.id=d.certificate_id JOIN project p ON p.id=x.project_id WHERE d.company_id=@p0 AND d.id=@p1",Company(h),id);
    var existing=await Store.Rows(c,"SELECT id,reference FROM invoice WHERE company_id=@p0 AND certificate_id=@p1",Company(h),d.Text("certificate_id"));if(existing.Count>0)return existing[0]!;
    Billing.Require(d.Text("state")=="Approved"&&d["confirmation"] is JsonObject&&d["confirmation"]!.Text("hash")==d.Text("snapshot_hash"),"Final issue requires client confirmation of the approved revision.");
    Billing.Require(b.Text("tax_reason").Length>5,"Record the reviewed tax treatment. Demo rules are not finance-approved.");var rate=b.Decimal("tax_rate");Billing.Require(rate is 0 or 5,"Local demo supports explicitly reviewed 0% or 5% only.");var date=b.Date("issue_date");Billing.Require(date>=DateOnly.Parse(d["confirmation"]!.Text("at")[..10]),"Issue date precedes confirmation.");
    var n=await Store.One(c,"UPDATE numbering SET invoice_next=invoice_next+1 WHERE company_id=@p0 RETURNING invoice_next-1 AS number",Company(h));var profile=await Organization.Snapshot(c,Company(h));var prefix=profile.Text("invoice_prefix");if(prefix=="")prefix="INV";var reference=prefix+"/"+date.Year+"/"+n.Integer("number").ToString("D6");var iid=Id();var net=d.Decimal("settlement");var vat=Billing.Money(net*rate/100);var confirmation=d["confirmation"]!.DeepClone().AsObject();confirmation["tax_reason"]=b.Text("tax_reason");confirmation["tax_rate"]=rate;
    await Store.Exec(c,"INSERT INTO invoice(id,company_id,project_id,customer_id,certificate_id,reference,issue_date,due_date,net,vat,total,category,confirmation,organization_snapshot) VALUES(@p0,@p1,@p2,@p3,@p4,@p5,@p6,@p7,@p8,@p9,@p10,@p11,@p12::jsonb,@p13::jsonb)",iid,Company(h),d.Text("project_id"),d.Text("customer_id"),d.Text("certificate_id"),reference,date,date.AddDays(30),net,vat,net+vat,d.Text("category"),confirmation.ToJsonString(),profile.ToJsonString());
    if(b["vat_details"] is JsonObject details)await Vat.ReviewInvoice(c,Company(h),Actor(h),iid,details);
    await Store.Exec(c,"UPDATE draft_invoice SET status='Issued' WHERE id=@p0",id);await Store.Audit(c,Company(h),Actor(h),"Final invoice issued",iid,new{reference,net,vat});return JsonSerializer.SerializeToNode(new{id=iid,reference})!;});});
