api.MapGet("/receipts",async(HttpContext h)=>{await using var c=await store.Open();return await Store.Rows(c,$"SELECT r.*,c.name AS customer,({Corrections.CashSql("r","'9999-12-31'::date")}) AS unapplied,EXISTS(SELECT 1 FROM financial_correction f WHERE f.receipt_id=r.id AND f.kind='Receipt reversal') AS reversed FROM receipt r JOIN customer c ON c.id=r.customer_id WHERE r.company_id=@p0 ORDER BY receipt_date DESC",Company(h));});
api.MapPost("/receipts",async(HttpContext h,JsonObject b)=>{Role(h,"Accountant","Finance Administrator","Collections Officer");return await store.Transaction(Company(h),async c=>{var id=Id();Billing.Require(b.Decimal("amount")>0&&b.Text("reference")!="","Positive amount and bank reference required.");await Store.Exec(c,"INSERT INTO receipt(id,company_id,customer_id,reference,receipt_date,amount,method) VALUES(@p0,@p1,@p2,@p3,@p4,@p5,@p6)",id,Company(h),b.Text("customer_id"),b.Text("reference"),b.Date("receipt_date"),Billing.Money(b.Decimal("amount")),b.Text("method"));await Store.Audit(c,Company(h),Actor(h),"Receipt recorded",id,b);return new{id};});});
api.MapPost("/allocations",async(HttpContext h,JsonObject b)=>{Role(h,"Accountant","Finance Administrator");return await store.Transaction(Company(h),async c=>{var r=await Corrections.Receipt(c,Company(h),b.Text("receipt_id"));var i=await Corrections.Invoice(c,Company(h),b.Text("invoice_id"));Billing.Require(r.Text("customer_id")==i.Text("customer_id"),"Receipt and invoice customer mismatch.");var amount=Billing.Money(b.Decimal("amount"));Billing.Allocate(r.Decimal("available"),i.Decimal("open"),amount);var date=b.Date("effective_date");Billing.Require(date>=DateOnly.Parse(r.Text("receipt_date"))&&date>=DateOnly.Parse(i.Text("issue_date")),"Allocation cannot predate receipt or invoice.");await Corrections.EnsureChronology(c,Company(h),i.Text("id"),r.Text("id"),date);var id=Id();await Store.Exec(c,"INSERT INTO allocation(id,company_id,customer_id,receipt_id,invoice_id,amount,effective_date) VALUES(@p0,@p1,@p2,@p3,@p4,@p5,@p6)",id,Company(h),r.Text("customer_id"),r.Text("id"),i.Text("id"),amount,date);await Store.Audit(c,Company(h),Actor(h),"Receipt allocated",id,b);return new{id};});});
api.MapGet("/audit",async(HttpContext h)=>{Role(h,"Finance Administrator","Auditor","System Administrator");await using var c=await store.Open();return await Store.Rows(c,"SELECT * FROM audit_event WHERE company_id=@p0 ORDER BY sequence DESC LIMIT 250",Company(h));});
api.MapGet("/integrations",()=>new[]{new{name="Tally",mode="Simulator",state="Not connected",detail="XML/HTTP bridge requires installed-version verification and mapping sign-off."},new{name="Zoho Books",mode="Simulator",state="Not connected",detail="OAuth, organization and regional endpoint required."},new{name="Microsoft Outlook",mode="Disabled",state="Consent required",detail="Share creates a preview; no email is sent. Graph tenant consent required."},new{name="UAE e-Invoicing ASP",mode="Simulator",state="Finance review required",detail="Provider profile, schema and applicability must be validated."}});
api.MapPost("/simulator",async(HttpContext h,JsonObject b)=>{Role(h,"Finance Administrator","System Administrator");return await store.Transaction(Company(h),async c=>{Billing.Require(new[]{"Tally","Zoho Books","UAE e-Invoicing ASP"}.Contains(b.Text("adapter")),"Unknown simulator.");var key=b.Text("idempotency_key");Billing.Require(key.Length>5,"An idempotency key is required.");var id=Id();await Store.Exec(c,"INSERT INTO outbox(id,company_id,kind,idempotency_key,payload,status,result) VALUES(@p0,@p1,@p2,@p3,@p4::jsonb,'Simulated',@p5::jsonb) ON CONFLICT(company_id,kind,idempotency_key) DO NOTHING",id,Company(h),b.Text("adapter"),key,b.ToJsonString(),"{\"simulator\":true,\"acknowledged\":true,\"productionVerified\":false}");return await Store.One(c,"SELECT * FROM outbox WHERE company_id=@p0 AND kind=@p1 AND idempotency_key=@p2",Company(h),b.Text("adapter"),key);});});
api.MapGet("/jobs",async(HttpContext h)=>{Role(h,"Finance Administrator","System Administrator");await using var c=await store.Open();return await Store.Rows(c,"SELECT * FROM outbox WHERE company_id=@p0 ORDER BY created_at DESC LIMIT 100",Company(h));});
Corrections.Map(api,store,Company,Actor,Role);
Documents.Map(api,store,data,Company,Actor,Role,root);
Imports.Map(api,store,Company,Actor,Role);
app.MapMethods("/api/{**path}",["GET","POST","PUT","PATCH","DELETE"],()=>Results.NotFound(new{error="This API feature is not implemented."}));
var web=Path.Combine(root,"apps/web/dist");if(Directory.Exists(web)){app.UseDefaultFiles(new DefaultFilesOptions{FileProvider=new Microsoft.Extensions.FileProviders.PhysicalFileProvider(web)});app.UseStaticFiles(new StaticFileOptions{FileProvider=new Microsoft.Extensions.FileProviders.PhysicalFileProvider(web)});app.MapFallbackToFile("index.html",new StaticFileOptions{FileProvider=new Microsoft.Extensions.FileProviders.PhysicalFileProvider(web)});}
app.Run();
